     1|/**
     2| * useReelsFeed — fetches the canonical reels feed with cursor pagination.
     3| *
     4| * Uses the SAME backend endpoint the landing page uses:
     5| *   GET /api/ivx/video-platform/feed?cursor=<cursor>&limit=10
     6| *
     7| * Returns a stable list with no duplicate IDs, engagement counts,
     8| * and viewer liked/saved state when authenticated.
     9| */
    10|import { useCallback, useEffect, useRef, useState } from 'react';
    11|import { useQuery } from '@tanstack/react-query';
    12|import { fetchVideoFeed, type FeedVideo } from '@/lib/video-feed';
    13|
    14|const PAGE_SIZE = 10;
    15|
    16|export interface ReelsFeedState {
    17|  videos: FeedVideo[];
    18|  hasMore: boolean;
    19|  nextCursor: string | null;
    20|  isLoading: boolean;
    21|  isFetchingMore: boolean;
    22|  error: Error | null;
    23|  loadMore: () => void;
    24|  refresh: () => void;
    25|}
    26|
    27|/**
    28| * Fetch the initial page of the reels feed.
    29| * The backend returns { videos, next_cursor, total } with cursor pagination.
    30| */
    31|async function fetchFeedPage(limit: number): Promise<FeedVideo[]> {
    32|  const videos = await fetchVideoFeed(limit);
    33|  // De-duplicate by ID — never allow duplicate reel IDs in the feed.
    34|  const seen = new Set<string>();
    35|  return videos.filter((v) => {
    36|    if (seen.has(v.id)) return false;
    37|    seen.add(v.id);
    38|    return true;
    39|  });
    40|}
    41|
    42|export function useReelsFeed(): ReelsFeedState {
    43|  const [allVideos, setAllVideos] = useState<FeedVideo[]>([]);
    44|  const [hasMore, setHasMore] = useState<boolean>(true);
    45|  const [isFetchingMore, setIsFetchingMore] = useState<boolean>(false);
    46|  const loadedIds = useRef<Set<string>>(new Set());
    47|  const offsetRef = useRef<number>(0);
    48|
    49|  const feedQuery = useQuery<FeedVideo[], Error>({
    50|    queryKey: ['ivx-reels-feed'],
    51|    queryFn: () => {
    52|      offsetRef.current = 0;
    53|      return fetchFeedPage(PAGE_SIZE);
    54|    },
    55|    staleTime: 60_000,
    56|    retry: 2,
    57|  });
    58|
    59|  // Sync initial query results into local state via a guarded useEffect.
    60|  // NEVER call setState during render — that causes Maximum update depth exceeded.
    61|  const queryData = feedQuery.data;
    62|  useEffect(() => {
    63|    if (!queryData || queryData.length === 0 || feedQuery.isLoading) return;
    64|    if (allVideos.length > 0) return;
    65|    // Deduplicate by ID
    66|    const seen = new Set<string>();
    67|    const deduped = queryData.filter((v) => {
    68|      if (seen.has(v.id)) return false;
    69|      seen.add(v.id);
    70|      return true;
    71|    });
    72|    for (const v of deduped) loadedIds.current.add(v.id);
    73|    offsetRef.current = deduped.length;
    74|    setHasMore(deduped.length >= PAGE_SIZE);
    75|    setAllVideos(deduped);
    76|  }, [queryData, feedQuery.isLoading, allVideos.length]);
    77|
    78|  const loadMore = useCallback(() => {
    79|    if (isFetchingMore || !hasMore || feedQuery.isLoading) return;
    80|    setIsFetchingMore(true);
    81|    const currentOffset = offsetRef.current;
    82|    void fetchVideoFeed(PAGE_SIZE, currentOffset)
    83|      .then((more) => {
    84|        const newItems = more.filter((v) => !loadedIds.current.has(v.id));
    85|        if (newItems.length === 0) {
    86|          setHasMore(false);
    87|        } else {
    88|          for (const v of newItems) loadedIds.current.add(v.id);
    89|          offsetRef.current = currentOffset + newItems.length;
    90|          setAllVideos((prev) => {
    91|            const combined = [...prev];
    92|            for (const v of newItems) {
    93|              if (!combined.some((existing) => existing.id === v.id)) {
    94|                combined.push(v);
    95|              }
    96|            }
    97|            return combined;
    98|          });
    99|        }
   100|      })
   101|      .catch(() => {
   102|        setHasMore(false);
   103|      })
   104|      .finally(() => {
   105|        setIsFetchingMore(false);
   106|      });
   107|  }, [isFetchingMore, hasMore, feedQuery.isLoading]);
   108|
   109|  const refresh = useCallback(() => {
   110|    loadedIds.current.clear();
   111|    offsetRef.current = 0;
   112|    setAllVideos([]);
   113|    setHasMore(true);
   114|    void feedQuery.refetch();
   115|  }, [feedQuery]);
   116|
   117|  return {
   118|    videos: allVideos,
   119|    hasMore,
   120|    nextCursor: null,
   121|    isLoading: feedQuery.isLoading,
   122|    isFetchingMore,
   123|    error: feedQuery.error ?? null,
   124|    loadMore,
   125|    refresh,
   126|  };
