   175|export async function downloadFeedVideo(
   176|  videoId: string,
   177|  title: string | null,
   178|): Promise<{ success: boolean; uri?: string; error?: string }> {
   179|  const url = getVideoDownloadUrl(videoId);
   180|
   181|  if (Platform.OS === 'web') {
   182|    try {
   183|      const w = (globalThis as { window?: { open?: (u: string, t: string) => unknown } }).window;
   184|      w?.open?.(url, '_blank');
   185|      return { success: true };
   186|    } catch (err) {
   187|      return { success: false, error: (err as Error).message };
   188|    }
   189|  }
